import 'package:flutter/material.dart';
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,home:const Tela());}
class Tela extends StatefulWidget{const Tela({super.key});@override State<Tela> createState()=>_TelaState();}
class _TelaState extends State<Tela>{final nota1=TextEditingController(),nota2=TextEditingController(),nota3=TextEditingController();String resultado='';void calcular(){final a=double.tryParse(nota1.text.replaceAll(',','.')),b=double.tryParse(nota2.text.replaceAll(',','.')),c=double.tryParse(nota3.text.replaceAll(',','.'));if(a==null||b==null||c==null){setState(()=>resultado='Informe as três notas.');return;}final media=(a+b+c)/3;setState(()=>resultado='Média: ${media.toStringAsFixed(1)}\nSituação: ${media>=6?'Aprovado':'Reprovado'}');}void limpar(){nota1.clear();nota2.clear();nota3.clear();setState(()=>resultado='');}@override void dispose(){nota1.dispose();nota2.dispose();nota3.dispose();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Calculadora de média')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:nota1,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Nota 1')),TextField(controller:nota2,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Nota 2')),TextField(controller:nota3,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Nota 3')),const SizedBox(height:20),Row(mainAxisAlignment:MainAxisAlignment.center,children:[ElevatedButton(onPressed:calcular,child:const Text('Calcular')),const SizedBox(width:12),ElevatedButton(onPressed:limpar,child:const Text('Limpar'))]),const SizedBox(height:24),Text(resultado)])));}
